options(warn = 2)
stopifnot(getRversion() == "4.6.1")
root <- normalizePath(getwd(), mustWork = TRUE)
out <- "/private/tmp/order72k-s2-width.bDuCS7"
w <- "audit/manuscript_nature_health/revision_2026_09_11/consolidated_display_repair_order72k"
e <- file.path(w, "environment_capture_recovery_001")
full <- function(p) ifelse(startsWith(p, "/"), p, file.path(root,p))
sha <- function(p) digest::digest(file=p,algo="sha256",serialize=FALSE)
pin <- function(p) { f <- full(p); stopifnot(file.exists(f),!dir.exists(f),Sys.readlink(f)==""); data.frame(path=p,sha256=sha(f),bytes=unname(file.info(f)$size)) }
checks <- list()
ck <- function(id,ok,detail) { checks[[length(checks)+1L]] <<- data.frame(check=id,pass=isTRUE(ok),detail=detail); if(!isTRUE(ok))stop(id) }
mp <- file.path(e,"stopped_visual_owner_manifest.csv")
ck("stop_manifest_sha",sha(full(mp))=="852fca237ffb23c1e294095aebd7894e150d350f4c41be32463a857711446a7e","Exact stopped owner seal")
m <- read.csv(full(mp),stringsAsFactors=FALSE)
ck("stop_manifest_shape",nrow(m)==295L && !anyDuplicated(m$path) && !mp %in% m$path,"295 unique non-circular rows")
obs <- do.call(rbind,lapply(m$path,pin))
recheck <- data.frame(m[,c("path","sha256","bytes")],observed_sha256=obs$sha256,observed_bytes=obs$bytes,pass=m$sha256==obs$sha256 & m$bytes==obs$bytes)
write.csv(recheck,file.path(out,"owner_manifest_rehash.csv"),row.names=FALSE)
ck("stop_members",all(recheck$pass),"295/295 exact")
ck("stop_record_sha",sha(full(file.path(e,"stopped_visual_return.md")))=="b5a24e0c4bdd47a18fee444ac01339eb4fd295268b64a2bd31e4cf745c15a13f","Exact STOPPED_VISUAL record")
orig <- read.csv(full(file.path(e,"after_854_rows.csv")),stringsAsFactors=FALSE)
hashes <- vapply(full(orig$path),sha,character(1))
ck("recovery_originals",nrow(orig)==854L && all(hashes==orig$expected_sha256),"854 current/original preflight rows exact")
write.csv(data.frame(path=orig$path,expected_sha256=orig$expected_sha256,observed_sha256=hashes,pass=hashes==orig$expected_sha256),file.path(out,"preservation_rehash.csv"),row.names=FALSE)
source_path <- "audit/manuscript_nature_health/figure_table_selection_assets/tbl-near-eye-metrics.html"
ck("source_table_sha",sha(full(source_path))=="6832c791ed3ebcf8895106dafe68c7c5118a12a74e37aacdeb8a84b02d9bfe97","Unchanged frozen S2 table")
source <- xml2::read_html(full(source_path))
render <- xml2::read_html(full(file.path(w,"preview_attempt1/main/ZaunerEtAl2026_NatHealth_phase3_brown.html")))
render <- xml2::xml_find_all(render,"//*[@id='tbl-near-eye-metrics']")
ck("one_rendered_s2",length(render)==1L,"One main preview S2 endpoint")
parts <- lapply(full(file.path(w,"capture_s2_attempt3",sprintf("supp_table_s2_part_%02d.html",1:3))),xml2::read_html)
cells <- function(d) xml2::xml_text(xml2::xml_find_all(d,".//tbody/tr/*[self::td or self::th]"))
norm <- function(x) trimws(gsub("[[:space:]\u00a0]+"," ",x,perl=TRUE))
a <- cells(source); b <- cells(render); c <- unlist(lapply(parts,cells),use.names=FALSE)
ck("all_cells_render_exact",length(a)==244L && identical(b,c),"244/244 captured cells exactly equal frozen rendered source")
ck("fragment_whitespace_only",identical(norm(a),norm(c)),"244/244 original fragment cell strings equal after whitespace-only normalization")
write.csv(data.frame(cell=seq_along(a),frozen_fragment=a,rendered=b,capture=c,render_exact=b==c,fragment_whitespace_only=norm(a)==norm(c)),file.path(out,"all_cell_comparison.csv"),row.names=FALSE)
node_text <- function(d,xp) xml2::xml_text(xml2::xml_find_first(d,xp))
ck("repeated_headers",all(vapply(parts,function(p)identical(node_text(render,".//thead"),node_text(p,".//thead")),logical(1))),"All three headers character-exact to rendered source")
ck("fragment_headers_whitespace",all(vapply(parts,function(p)identical(norm(node_text(source,".//thead")),norm(node_text(p,".//thead"))),logical(1))),"All headers equal original fragment after whitespace normalization")
ck("notes",all(vapply(parts[1:2],function(p)length(xml2::xml_find_all(p,".//tfoot"))==0L,logical(1))) && identical(node_text(render,".//tfoot"),node_text(parts[[3]],".//tfoot")) && identical(norm(node_text(source,".//tfoot")),norm(node_text(parts[[3]],".//tfoot"))),"Notes preserved on final part only; fragment differs only in whitespace")
payload <- function(d)unname(xml2::xml_attr(xml2::xml_find_all(d,".//tbody//img"),"src"))
ck("image_payloads",length(payload(source))==17L && identical(payload(source),unlist(lapply(parts,payload),use.names=FALSE)),"17/17 image payloads byte-exact")
old_helper <- full(file.path(w,"helpers/capture_word_tables.mjs"))
ck("old_helper",sha(old_helper)=="8dd21ba1d978e36d1cafa0669b7c2456306b66e996f013f44b86ebc2549e0174","Exact preimage")
new_helper <- file.path(out,"capture_word_tables_width_candidate.mjs")
old_css <- full(file.path(w,"project/order72k_layout.css"))
selection_css <- full("audit/manuscript_nature_health/consolidated_display_repair_2026_09_11/integration_candidate_order72k/project/order72k_layout.css")
ck("paired_css_preimages",sha(old_css)=="44b5a324d14ede154901a28005f042a7b1edc544a80e589a30ccaebe82a087c5" && sha(old_css)==sha(selection_css),"Identical frozen prepared CSS")
rt <- function(p)readChar(p,file.info(p)$size,useBytes=TRUE)
before <- rt(old_helper); after <- rt(new_helper)
pairs <- list(
 c("targetWidth: 1490,","targetWidth: 1400,"),
 c("fixedWidths: [200, 80, 105, 86, 86, 86, 86, 86, 86, 86, 86, 86, 100, 231],","fixedWidths: [200, 40, 105, 86, 86, 86, 86, 86, 86, 86, 86, 86, 50, 231],"),
 c('table.querySelectorAll("thead th, thead td, tbody th, tbody td, tfoot th, tfoot td")','table.querySelectorAll("tbody tr > :nth-child(n+3):nth-child(-n+12)")'),
 c('rect.left < cellBox.left - 0.5 || rect.right > cellBox.right + 0.5 || rect.top < cellBox.top - 0.5 || rect.bottom > cellBox.bottom + 0.5','rect.left < cellBox.left - 0.5 || rect.right > cellBox.right + 0.5'),
 c('text:walker.currentNode.textContent,left:rect.left,right:rect.right,top:rect.top,bottom:rect.bottom,cellLeft:cellBox.left,cellRight:cellBox.right,cellTop:cellBox.top,cellBottom:cellBox.bottom','text:walker.currentNode.textContent,left:rect.left,right:rect.right,cellLeft:cellBox.left,cellRight:cellBox.right'),
 c('S2 all-cell text clipping:','S2 numerical text clipping:')
)
rev <- after
for(pair in pairs){ hit<-gregexpr(pair[1],rev,fixed=TRUE)[[1]];stopifnot(length(hit)==1L,hit[1]>0L);rev<-sub(pair[1],pair[2],rev,fixed=TRUE) }
ck("helper_exact_reverse",identical(rev,before),"Six bounded substitutions reconstruct exact helper preimage")
cssnew<-rt(file.path(out,"order72k_layout_width_candidate.css"));cssrev<-cssnew
for(pair in list(c("width:1490px","width:1400px"),c("width:80px","width:40px"),c("width:100px","width:50px")))cssrev<-gsub(pair[1],pair[2],cssrev,fixed=TRUE)
ck("css_exact_reverse",identical(cssrev,rt(old_css)),"Only full S2 canvas and two column widths change")
old_widths <- c(200,40,105,rep(86,9),50,231)
new_widths <- c(200,80,105,rep(86,9),100,231)
ck("width_boundary",sum(old_widths)==1400 && sum(new_widths)==1490 && identical(which(old_widths!=new_widths),c(2L,13L)),"Unit40->80, Scaling50->100; every other column unchanged; canvas1490")
write.csv(data.frame(column=1:14,old_px=old_widths,new_px=new_widths),file.path(out,"width_matrix.csv"),row.names=FALSE)
paths<-sort(unique(c(mp,file.path(e,c("stopped_visual_return.md","stopped_visual_owner_seal.json","execution_receipt.json","server_session.json","teardown_receipt.json","capture_structure_and_visual_checks.csv","all_cell_text_comparison.csv","reconcile_capture.R","reconciliation_session.txt","after_854_rows.csv")),file.path(w,"helpers/capture_word_tables.mjs"),file.path(w,"helpers/prepare_word_manuscript.py"),file.path(w,"project/order72k_layout.css"),"audit/manuscript_nature_health/consolidated_display_repair_2026_09_11/integration_candidate_order72k/project/order72k_layout.css",source_path,full(file.path(w,"preview_attempt1/main/ZaunerEtAl2026_NatHealth_phase3_brown.html")),file.path(w,"capture_s2_attempt3",list.files(full(file.path(w,"capture_s2_attempt3")))),file.path(w,"capture_attempt1",list.files(full(file.path(w,"capture_attempt1")))))))
pins<-do.call(rbind,lapply(paths,pin));write.csv(pins,file.path(out,"input_pins.csv"),row.names=FALSE)
write.csv(do.call(rbind,checks),file.path(out,"checks.csv"),row.names=FALSE)
writeLines(c(capture.output(sessionInfo()),paste("digest",packageVersion("digest")),paste("xml2",packageVersion("xml2"))),file.path(out,"session.txt"))
cat(sprintf("ORDER72K_S2_WIDTH_AUDIT=PASS checks=%d owner=295 originals=854 cells=244 images=17 inputs=%d browser_runs=0 R=%s\n",length(checks),nrow(pins),getRversion()))
print(do.call(rbind,lapply(c(new_helper,file.path(out,"order72k_layout_width_candidate.css")),pin)),row.names=FALSE)
